function getHappyString(n, k) {
  let res = [];
  function backtrack(s) {
    if (s.length === n) { res.push(s); return; }
    for (let char of ['a', 'b', 'c']) {
      if (s.length === 0 || s[s.length - 1] !== char) {
        backtrack(s + char);
      }
    }
  }
  backtrack('');
  return res[k - 1] || '';
}
